use kimo_core::{color::neutral,effects::Frame};
#[test]fn neutral_trim_rejects_outlier(){let mut d=vec![];for _ in 0..10{d.extend([0.2,0.4,0.1,1.]);}d.extend([20.,40.,10.,1.]);let f=Frame{w:11,h:1,d};let v=neutral::sample(&f,0,[0.,0.,1.,1.],0.1).unwrap();let gain=v["suggested_gain_rgb"].as_array().unwrap();let m=v["trimmed_mean_rgb"].as_array().unwrap();let values:Vec<_>=(0..3).map(|j|gain[j].as_f64().unwrap()*m[j].as_f64().unwrap()).collect();assert!((values[0]-values[1]).abs()<1e-12);assert!((values[1]-values[2]).abs()<1e-12);assert!((m[0].as_f64().unwrap()-0.2).abs()<1e-6);}
#[test]fn invalid_neutral_region(){let f=Frame{w:2,h:2,d:vec![0.;16]};assert!(neutral::sample(&f,0,[0.,0.,1.,1.],0.1).is_err());assert!(neutral::sample(&f,0,[0.9,0.,0.5,1.],0.1).is_err());assert!(neutral::sample(&f,0,[0.,0.,1.,1.],0.5).is_err());}
